using Pn3DKit.Models;

namespace Pn3DKit.Utils;

/// <summary>可离线验证的实际列元数据适配策略，只解析明确约束，不将描述属性当作权限。</summary>
public static class PnPropertyMetadataPolicy
{
    /// <summary>SDK 明确的列属性约束，其余键不参与写权限判定。</summary>
    private static readonly HashSet<string> Constraints = new(StringComparer.OrdinalIgnoreCase)
    {
        "ReadOnly", "IsReadOnly", "System", "IsSystem", "Autogenerated", "IsAutogenerated",
        "Counter", "IsCounter", "Expression", "IsExpression"
    };

    /// <summary>根据列事实及必要规则求权限；Tag 专用流程惰性调用，普通字段不读取位号格式。</summary>
    /// <remarks>必要规则失败返回只读及详情；非获取属性不查询获取状态，不作试写来探测权限。</remarks>
    public static PnEditPermission Evaluate(PnColumnMetadata column, IEnumerable<string?> attributeNames,
        Func<string, string?> readAttribute, Func<bool> isAcquisition, Func<string?> acquisitionStatus,
        Func<PnEditPermission> tagPermission, Func<Exception, string>? describe = null)
    {
        try
        {
            bool readOnly = column.ReadOnly, system = column.System;
            bool automatic = column.Autogenerated || column.Counter, expression = column.Expression;
            foreach (string? name in attributeNames)
            {
                if (name == null || !Constraints.Contains(name)) continue;
                string value = readAttribute(name)?.Trim() ?? "";
                // 空扩展值不覆盖 SDK 已解析的布尔事实；描述信息无需读取。
                if (value.Length == 0) continue;
                if (name.Equals("Expression", StringComparison.OrdinalIgnoreCase)) { expression = true; continue; }
                bool flag = value == "1" || bool.TryParse(value, out bool parsed) && parsed;
                if (!flag && value != "0" && !value.Equals("false", StringComparison.OrdinalIgnoreCase))
                    return PnEditPermission.ReadOnly("无法确认列约束：" + name + "=" + value);
                if (name.Equals("ReadOnly", StringComparison.OrdinalIgnoreCase) || name.Equals("IsReadOnly", StringComparison.OrdinalIgnoreCase)) readOnly |= flag;
                else if (name.Equals("System", StringComparison.OrdinalIgnoreCase) || name.Equals("IsSystem", StringComparison.OrdinalIgnoreCase)) system |= flag;
                else if (name.Equals("IsExpression", StringComparison.OrdinalIgnoreCase)) expression |= flag;
                else automatic |= flag;
            }
            bool tag = column.Property.Equals("Tag", StringComparison.OrdinalIgnoreCase);
            var facts = new PnPermissionFacts(MetadataKnown: true, FieldReadOnly: readOnly, System: system,
                Automatic: automatic, Expression: expression, DrawingWritable: true, ProjectWritable: true,
                Enlisted: true, LayerLocked: false, Busy: false,
                SpecialAllowed: !column.Extension && (!column.Unique || tag) && column.SupportedType,
                UnknownReason: "扩展、唯一键或不支持的字段类型，未确认安全写入流程。");
            var permission = PnPropertyPolicy.Permission(facts);
            if (!permission.Allowed) return permission;
            if (isAcquisition())
                return PnEditPermission.ReadOnly("获取属性（" + (acquisitionStatus() ?? "类别获取规则") + "）：不解除获取、不改写来源。");
            return tag ? tagPermission() : permission;
        }
        catch (Exception ex)
        { return PnEditPermission.ReadOnly("无法确认写权限：" + (describe?.Invoke(ex) ?? ex.Message)); }
    }
}
